#!/usr/bin/env python3

def solve():
    with open('/tmp/test_parking.txt', 'r') as f:
        first_line = f.readline().split()
        n, m = int(first_line[0]), int(first_line[1])
        grid = [f.readline().strip() for _ in range(n)]

    print(f"Grid: {n}x{m}")
    for i, row in enumerate(grid):
        print(f"Row {i}: {row}")

    # Precompute left[i][j]
    left = [[0] * m for _ in range(n)]
    for i in range(n):
        cnt = 0
        for j in range(m):
            if grid[i][j] == '.':
                cnt += 1
            else:
                cnt = 0
            left[i][j] = cnt

    # Precompute up[i][j]
    up = [[0] * m for _ in range(n)]
    for j in range(m):
        cnt = 0
        for i in range(n):
            if grid[i][j] == '.':
                cnt += 1
            else:
                cnt = 0
            up[i][j] = cnt

    print("\nleft matrix:")
    for row in left:
        print(row)

    print("\nup matrix:")
    for row in up:
        print(row)

    # diff array
    diff = [[0] * (m + 2) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                continue

            max_h = up[i][j]
            current_min = left[i][j]

            # h=1
            diff[1][1] += 1
            if current_min + 1 <= m:
                diff[1][current_min + 1] -= 1

            # h=2 to max_h
            for h in range(2, max_h + 1):
                current_min = min(current_min, left[i - h + 1][j])
                diff[h][1] += 1
                if current_min + 1 <= m:
                    diff[h][current_min + 1] -= 1

    # Convert to counts
    ans = [[0] * m for _ in range(n)]
    for h in range(1, n + 1):
        running = 0
        row = ans[h-1]
        for w in range(1, m + 1):
            running += diff[h][w]
            row[w-1] = running

    print("\nAnswer matrix (n lines, m integers each):")
    for row in ans:
        print(' '.join(map(str, row)))

if __name__ == '__main__':
    solve()
